#include <bits/stdc++.h>
using namespace std;

using lo = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    lo n, m;
    cin >> n >> m;

    vector<pair<lo, lo>> factors;
    lo value = m;

    for (lo p = 2; p <= value / p; ++p) {
        if (value % p == 0) {
            lo exponent = 0;
            while (value % p == 0) {
                value /= p;
                ++exponent;
            }
            factors.push_back({p, exponent});
        }
    }

    if (value > 1) {
        factors.push_back({value, 1});
    }

    lo answer = LLONG_MAX;

    for (auto [prime, required] : factors) {
        lo available = 0;
        lo current = n;

        while (current > 0) {
            current /= prime;
            available += current;
        }

        answer = min(answer, available / required);
    }

    if (factors.empty()) answer = 0;

    cout << answer << '\n';
    return 0;
}

