using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, m;
    cin >> n >> m;

    vector<pair<int64, int>> factors;
    int64 value = m;

    for (int64 p = 2; p <= value / p; p += (p == 2 ? 1 : 2)) {
        if (value % p != 0) continue;

        int exponent = 0;
        while (value % p == 0) {
            value /= p;
            ++exponent;
        }
        factors.emplace_back(p, exponent);
    }

    if (value > 1) {
        factors.emplace_back(value, 1);
    }

    int64 answer = LLONG_MAX;

    for (const auto &[prime, exponent] : factors) {
        int64 count = 0;
        int64 current = n;

        while (current > 0) {
            current /= prime;
            count += current;
        }

        answer = min(answer, count / exponent);
    }

    cout << answer << '\n';
    return 0;
}

